class TimeMap {
public:
    // key -> list of (timestamp, value) pairs, sorted by timestamp
    // because set() timestamps for a key strictly increase, push_back keeps it sorted
    unordered_map<string, vector<pair<long long, string>>> store;

    void set(string key, string value, int timestamp) {
        store[key].push_back({ (long long)timestamp, value });
    }

    string get(string key, int timestamp) {
        auto it = store.find(key);
        if (it == store.end()) return "";

        vector<pair<long long, string>>& vec = it->second;
        int lo = 0, hi = (int)vec.size() - 1;
        int floorIdx = -1; // -1 means "no valid floor found yet"

        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (vec[mid].first <= timestamp) {
                floorIdx = mid;   // this index is a valid candidate
                lo = mid + 1;     // try to find an even later valid candidate
            } else {
                hi = mid - 1;     // this timestamp is too large, search earlier
            }
        }

        if (floorIdx == -1) return ""; // even the smallest stored timestamp exceeds target
        return vec[floorIdx].second;
    }
};

string get(string key, int timestamp) {
    auto it = store.find(key);
    if (it == store.end()) return "";

    vector<pair<long long, string>>& vec = it->second;

    // find first element whose timestamp is strictly greater than target
    auto pos = upper_bound(
        vec.begin(), vec.end(), (long long)timestamp,
        [](long long target, const pair<long long, string>& p) {
            return target < p.first;
        }
    );

    if (pos == vec.begin()) return ""; // nothing at or before target exists

    --pos; // step back one position: this is the floor
    return pos->second;
}
